"""Bilingual specialist context with separate units and like-for-like slope rows."""
from html import escape as e
import math
def render(data,lang):
    hr=lang=='hr';t=lambda a,b:b if hr else a
    def n(v,k=2):return '—' if v is None else f'{v:.{k}f}'.replace('.',',' if hr else '.')
    def tbl(headers,rows):return '<div class="table-scroll" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+str(c)+('</th>' if i==0 else '</td>') for i,c in enumerate(r))+'</tr>' for r in rows)+'</tbody></table></div>'
    def plot(field,label,scale=1,width=940):
        rows=data['observations'];values=[r[field]*scale for r in rows if r[field] is not None];upper=max(values) or 1;upper=math.ceil(upper/(10**math.floor(math.log10(upper))))*10**math.floor(math.log10(upper));x=lambda i:45+(width-70)*i/(len(rows)-1);y=lambda v:185-145*v/upper
        out=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} 225" role="img" aria-label="{e(label)}"><title>{e(label)}</title>'
        for j in range(4):
            v=upper*j/3;out+=f'<line x1="45" x2="{width-25}" y1="{y(v)}" y2="{y(v)}" stroke="#d8e0e6"/><text x="39" y="{y(v)+4}" text-anchor="end" fill="#4f6470" font-size="12">{n(v,0)}</text>'
        points=[];segments=[]
        for i,r in enumerate(rows):
            if r[field] is None:
                if points:segments.append(points);points=[]
            else:points.append(f'{x(i):.2f},{y(r[field]*scale):.2f}')
        if points:segments.append(points)
        for seg in segments:out+='<polyline points="'+' '.join(seg)+'" fill="none" stroke="#165ce0" stroke-width="2"/>'
        idx=next(i for i,r in enumerate(rows) if r['period']=='2024-04');out+=f'<line x1="{x(idx)}" x2="{x(idx)}" y1="38" y2="185" stroke="#6b7780" stroke-dasharray="4 4"/>'
        for i,r in enumerate(rows):
            if r['period'].endswith('-01'):out+=f'<text x="{x(i)}" y="213" text-anchor="middle" fill="#4f6470" font-size="12">{r["period"][:4]}</text>'
        out+='</svg>'
        return f'<figure><h3>{e(label)}</h3><div class="legacy-wide">{out}</div><div class="legacy-narrow">{plot(field,label,scale,340)}</div></figure>' if width==940 else out
    rows=[]
    for sample in ['S0','S1','S3']:
        for freq in ['monthly','weekly']:
            r=next(r for r in data['slopes'] if r['sample']==sample and r['frequency']==freq)
            rows.append([sample,t(freq,{'monthly':'mjesečno','weekly':'tjedno'}[freq]),n(-100*r['estimate'],3),n(-100*r['hi'],3)+' / '+n(-100*r['lo'],3),int(r['N'])])
    slopes=tbl([t('Sample','Uzorak'),t('Frequency','Frekvencija'),t('Share slope · pp per inflation pp','Nagib udjela · pb po pb inflacije'),'95% CI',t('Fitted N','N u regresiji')],rows)
    direct=next(r for r in data['interactions'] if r['frequency']=='weekly' and r['adjustment']=='trend')
    table=tbl([t('Month','Mjesec'),t('Own-source count','Broj vlastitih objava'),t('Weighted share %','Ponderirani udio %'),t('Government share %','Udio Vlade %'),t('Legacy L2','Stari L2'),t('Syndicated / original flags','Oznake preneseno / izvorno'),t('Formal / generic priority routes','Prioritet naziv / opći izrazi'),t('Inflation / additional monetary / other','Inflacija / dodatna monetarna / ostalo')],[[r['period'],n(r['hnb_comm'],0),n(r['s_infl_core']*100 if r['s_infl_core'] is not None else None),n(r['gov_comm_share']*100 if r['gov_comm_share'] is not None else None),n(r['n_all'],0),n(r['n_synd'],0)+' / '+n(r['n_orig'],0),n(r['n_formal'],0)+' / '+n((r['n_sredisnja']+r['n_centralna']) if r['n_formal'] is not None else None,0)+' / '+n(r['n_other_retrieval'],0),(' / '.join(n(v,0) for v in [r['n_infl_hnb'],r['n_monpol_hnb']-r['n_infl_hnb'],r['n_all']-r['n_monpol_hnb']]) if r['n_all'] is not None else '—')] for r in data['observations']])
    supply=next(r for r in data['supply_controls'] if r['frequency']=='weekly' and r['sample']=='S1' and r['extra_control']=='log_hnb_comm');own=next(r for r in data['supply_outcomes'] if r['frequency']=='weekly' and r['sample']=='S1' and r['outcome']=='log_hnb_comm')
    return f'''<section class="wrap section" id="legacy-context"><p class="eyebrow">{t('Specialist diagnostics / frozen inputs','Specijalistička dijagnostika / zamrznuti ulazi')}</p><h2>{t('Separate supply, relative representation and collection.','Razlikujte ponudu, relativnu zastupljenost i prikupljanje.')}</h2><p>{t('These aligned panels use the saved inflation-study archive, January 2021–May 2026. Own-source counts are vendor-captured HNB-channel candidates, not a complete official-document inventory. Government communication refers to the government, not the governor. The media gap is January–March 2024; the dashed line is April 2024.','Usklađeni prikazi koriste spremljeni arhiv inflacijske studije, od siječnja 2021. do svibnja 2026. Brojevi vlastitih objava kandidati su iz HNB-ovih kanala koje je zabilježio dobavljač, a ne potpuni popis službenih dokumenata. Vladina komunikacija odnosi se na Vladu, ne na guvernera. Medijski jaz traje od siječnja do ožujka 2024.; isprekidana crta označava travanj 2024.')}</p><div class="legacy-aligned">{plot('hnb_comm',t('Vendor-captured HNB-channel candidates · count','Zabilježeni kandidati HNB-ovih kanala · broj'))}{plot('s_infl_core',t('Weighted institutional share in inflation coverage · %','Ponderirani institucionalni udio u inflacijskim objavama · %'),100)}{plot('gov_comm_share',t('Government communication share of monitored inflation records · %','Udio komunikacije Vlade u praćenim inflacijskim zapisima · %'),100)}</div><p class="source">{t('Source: frozen panel_monthly.csv; separate axes and units. Observed coverage is not a constant sampling fraction.','Izvor: zamrznuti panel_monthly.csv; odvojene osi i jedinice. Opaženi obuhvat nije stalan udio uzorkovanja.')}</p><p>{t('Adding the measured own-supply control leaves a positive inflation–gap association in the S1 weekly model','Dodavanje mjerene kontrole vlastite ponude zadržava pozitivnu povezanost inflacije i jaza u tjednom modelu S1')}: β = {n(supply['estimate'],6)}, 95% CI {n(supply['lo'],6)} / {n(supply['hi'],6)}. {t('The own-supply outcome slope is','Nagib ishoda vlastite ponude iznosi')} {n(own['estimate'],4)} (p = {n(own['p'],3)}). {t('An inconclusive slope is not evidence that supply was constant; no transmission failure is identified.','Neodređen nagib nije dokaz stalne ponude; nije identificiran neuspjeh prijenosa poruka.')}</p><details><summary>{t('Compare like slopes across S0, S1 and S3','Usporedite iste nagibe za S0, S1 i S3')}</summary><p>{t('Equation 9b, IAG_primary, pi_t coefficient, transformed by −100 to weighted-share percentage points. S0: 2021–2023; S1: through May 2026 with media gaps; S3: April 2024–May 2026. Eligible monthly/weekly N: S0 36/157, S1 62/270, S3 26/113. Fitted N is below.','Jednadžba 9b, IAG_primary, koeficijent pi_t, pomnožen s −100 za postotne bodove ponderiranog udjela. S0: 2021.–2023.; S1: do svibnja 2026. s medijskim prazninama; S3: travanj 2024. – svibanj 2026. Prihvatljivi mjesečni/tjedni N: S0 36/157, S1 62/270, S3 26/113. N u regresiji prikazan je u tablici.')}</p>{slopes}<p>{t('The direct weekly period-interaction test with trends has p','Izravni tjedni test interakcije razdoblja uz trendove ima p')} = {n(direct['p'],3)}. {t('A larger later point estimate does not establish a stronger slope. Euro before/after and collection-boundary tests are confounded comparisons, not causal policy effects.','Veća kasnija točkasta procjena ne utvrđuje snažniji nagib. Usporedbe prije i poslije uvođenja eura te testovi granice prikupljanja opterećeni su drugim promjenama i ne predstavljaju uzročne učinke politike.')}</p></details><details><summary>{t('Monthly supply, retrieval and composition table','Mjesečna tablica ponude, pronalaženja i sastava')}</summary>{table}<p>{t('Syndicated/original are saved flags, not distinct-text identities. Formal/generic are priority routes within legacy L2; three residual records across three months are shown as other. Generic-only share is not an attribution-error estimate. Keyword monetary-policy counts include inflation; the additional category subtracts inflation. None is a learned topic or the new HNB_MEDIA population.','Preneseno/izvorno spremljene su oznake, a ne identiteti različitih tekstova. Naziv/opći izrazi međusobno su isključivi prioritetni putovi u starom L2. Udio općih izraza nije procjena pogrešnog pripisivanja. Monetarne ključne riječi uključuju inflaciju; dodatna kategorija oduzima inflaciju. Nijedna nije naučena tema ni novi skup HNB_MEDIA.')}</p></details><p><a href="data/legacy-context.csv">{t('Series · CSV','Serije · CSV')}</a> · <a href="data/legacy-context.json">{t('Saved estimates, sources and definitions · JSON','Spremljene procjene, izvori i definicije · JSON')}</a></p></section>'''
